use super::*;
use semio_framework_value::RetainedCloneSource;
fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:4096,maximum_release_bytes:262144,maximum_depth:4096}}
fn observe<T>(run:impl FnOnce()->(T,RetainedCloneProgress))->T{let((value,p),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(run);assert!(p.fits(grant()));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));value}
#[test]
fn original_canonical_operation_comparison_uses_same_typed_source_and_original_octets(){let law:serde_json::Value=serde_json::from_str(include_str!("../../../🧳️original/🔣️.json")).unwrap();for case in law["cases"].as_array().unwrap(){for changed in [false,true]{for cut in [0,1,2,8,32,128,usize::MAX]{let text=case["text"].as_str().unwrap().repeat(case["repeat"].as_u64().unwrap()as usize);let mut expected=[b"op".as_slice(),serde_json::to_vec(&text).unwrap().as_slice()].concat();if changed{expected[0]=b'x';}let stock=RetainedCloneGrant{maximum_capacity_bytes:1<<24,..grant()};let (mut source,_)=RetainedCloneSource::admit_owned(text,(),stock).map_err(|(error,..)|error).unwrap();let pointer=source.borrow().get().as_ptr();let mut owner=OriginalOperationWireComparison::default();let mut refused=false;for index in 0..100000{if index==cut||owner.prepared(){break}let input=source.borrow();let d=owner.demands(input,&expected,4096).unwrap();assert!(d.copy_bytes<=4096&&d.capacity_bytes<=4096);for axis in 0..5{let amount=match axis{0=>1,1=>d.copy_bytes,2=>d.capacity_bytes,3=>d.release_bytes,_=>d.depth};if amount==0{continue}let mut g=grant();match axis{0=>g.maximum_items=0,1=>g.maximum_copy_bytes=amount-1,2=>g.maximum_capacity_bytes=amount-1,3=>g.maximum_release_bytes=amount-1,_=>g.maximum_depth=amount-1}observe(||{let p=owner.advance(input,&expected,ArtifactOperationWire::canonical(),1<<24,g).unwrap();assert_eq!(p,Default::default());((),p)});}let (step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance(input,&expected,ArtifactOperationWire::canonical(),1<<24,grant()));match step{Ok(p)=>{assert!(p.fits(grant()));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));},Err(error)=>{assert!(changed);assert_eq!(error.kind,ValueRefusalKind::InvalidValue);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));refused=true;break}}let foreign=expected.clone();let(error,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance(source.borrow(),&foreign,ArtifactOperationWire::canonical(),1<<24,grant()).unwrap_err());assert_eq!(error.kind,ValueRefusalKind::InvariantViolated);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(index<99999)}if cut==usize::MAX{assert_eq!(refused,changed);assert_eq!(owner.prepared(),!changed);}for index in 0..100000{if owner.terminal_is_empty(){break}observe(||{let step=owner.close_step(grant()).unwrap();((),step.progress())});assert!(index<99999)}assert_eq!(source.borrow().get().as_ptr(),pointer);for index in 0..100000{if source.terminal_is_empty(){break}observe(||{let step=source.close_step(grant()).unwrap();((),step.progress())});assert!(index<99999)}assert!(source.terminal_is_empty());}}}}
